mapper.select:
SELECT status
FROM biz_idempotent
WHERE biz_no = #{bizNo}
  AND op_type = #{opType}
  AND platform_id = #{platformId}

mapper.update:
UPDATE biz_idempotent
SET status = #{status},
    update_time = NOW()
WHERE biz_no = #{bizNo}
  AND op_type = #{opType}
  AND platform_id = #{platformId}
